    zh: { pregunta: "去增长理论针对当前经济模式提出了什么主张？", opciones: ["加速工业增长以克服贫困", "减少生产和消费以实现环境可持续性和福祉", "维持增长但改善分配"], explicacion: "去增长理论质疑无限增长的逻辑，主张缩减经济规模以尊重生态极限。" },
