/**
 * Devuelve la pregunta `p` (tal como viene de questions.js) con su
 * contenido traducido al idioma actual, si existe traducción disponible.
 * Si no la hay, devuelve la pregunta original en español sin romper nada.
 *
 * No modifica el objeto original: devuelve una copia superficial con los
 * campos traducidos, dejando el resto de propiedades intactas (por si en
 * el futuro se añaden más campos a las preguntas).
 *
 * @param {{pregunta: string, opciones: string[], correcta: number, explicacion?: string}} p
 * @returns {{pregunta: string, opciones: string[], correcta: number, explicacion?: string}}
 */
function obtenerPreguntaTraducida(p) {
  if (!p) return p;
  const lang = (typeof config !== "undefined" && config.idioma) || "es";
  if (lang === "es") return p;

  const traduccion = TRADUCCIONES_PREGUNTAS[p.pregunta];
  if (!traduccion || !traduccion[lang]) return p; // sin traducción todavía: fallback a español

  const t = traduccion[lang];
  return Object.assign({}, p, {
    pregunta: t.pregunta || p.pregunta,
    // Si las opciones traducidas no coinciden en cantidad con el original,
    // se ignoran para no desalinear el índice de la respuesta correcta.
    opciones: (Array.isArray(t.opciones) && t.opciones.length === p.opciones.length) ? t.opciones : p.opciones,
    explicacion: t.explicacion || p.explicacion
  });
}

// Se exponen ambos en window para que preguntas/resources/script.js (y
// cualquier otro módulo futuro) pueda usarlos sin depender del orden
// exacto de scripts más allá de "cargar este archivo después de
// questions.js y antes de script.js".
window.TRADUCCIONES_PREGUNTAS = TRADUCCIONES_PREGUNTAS;
window.obtenerPreguntaTraducida = obtenerPreguntaTraducida;
